<script setup>
import { onMounted, ref } from "vue"; import { api } from "../api";
const docs=ref([]), query=ref(""), results=ref([]), selected=ref(null), loading=ref(true), searching=ref(false), error=ref("");
async function load(){loading.value=true;try{docs.value=await api("/knowledge/policies");}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function search(){if(!query.value.trim())return;searching.value=true;error.value="";try{const data=await api("/knowledge/search",{method:"POST",body:JSON.stringify({question:query.value})});results.value=data.results;}catch(e){error.value=e.message;}finally{searching.value=false;}}
onMounted(load);
</script>
<template><div class="page-stack"><section class="welcome-row"><div><div class="eyebrow">RETRIEVAL KNOWLEDGE</div><h2>RAG 知识库</h2><p>只读展示现有政策文件；检索测试使用现有 Chroma、Embedding 和 Top-K 配置。</p></div><span class="read-only-badge">只读知识源</span></section><section class="content-card search-card"><form class="search-form" @submit.prevent="search"><div><label>检索测试</label><input v-model="query" placeholder="输入售后政策问题，例如：退款多久到账？"></div><button class="button button-primary" :disabled="searching">{{searching?"检索中…":"运行检索"}}</button></form><p class="muted">提交后会按现有 RAG 配置向 Embedding 服务发送查询文本；不会修改向量库。</p><div v-if="error" class="inline-error">{{error}}</div><div v-if="results.length" class="evidence-list"><article v-for="(r,i) in results" :key="`${r.source_id}-${i}`" class="evidence-card"><div class="evidence-heading"><strong>{{r.source_id}} · {{r.title}}</strong><span>distance {{Number(r.distance).toFixed(4)}}</span></div><p>{{r.content}}</p></article></div></section><section class="content-card"><div class="section-heading"><div><h3>政策文档 <span class="count-badge">{{docs.length}}</span></h3><p>来源：项目的 data/policies 目录。当前不提供上传或重建索引。</p></div></div><div v-if="loading" class="state-card">正在读取政策目录…</div><div v-else class="doc-grid"><button v-for="doc in docs" :key="doc.document_id" class="doc-card" @click="selected=doc"><span class="doc-icon">▤</span><span><strong>{{doc.document_id}}</strong><small>{{doc.title}}</small></span><span class="doc-arrow">→</span></button></div></section><div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="detail-modal"><button class="modal-close" @click="selected=null">关闭</button><div class="eyebrow">POLICY SOURCE · READ ONLY</div><h3>{{selected.document_id}} · {{selected.title}}</h3><pre class="policy-content">{{selected.content}}</pre></section></div></div></template>
